function firstMatch(text, patterns) {

  for (const regex of patterns) {

    const match =
      text.match(regex);

    if (
      match &&
      match[1] !== undefined
    ) {
      return String(match[1]).trim();
    }
  }

  return null;
}


function amount(value) {

  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  let text =
    String(value)
      .trim()
      .replace(/\s/g, '')
      .replace(/[^\d,.\-]/g, '');

  if (!text) {
    return null;
  }

  const comma =
    text.lastIndexOf(',');

  const dot =
    text.lastIndexOf('.');

  // 1.234,56
  if (comma > dot) {

    text =
      text
        .replace(/\./g, '')
        .replace(',', '.');
  }

  // 1,234.56
  else if (
    dot > comma &&
    comma !== -1
  ) {

    text =
      text.replace(/,/g, '');
  }

  // 17,70
  else if (
    comma !== -1 &&
    dot === -1
  ) {

    text =
      text.replace(',', '.');
  }

  const number =
    Number(text);

  return Number.isFinite(number)
    ? number
    : null;
}


function isoDate(value) {

  if (!value) {
    return null;
  }

  const text =
    String(value).trim();

  // DD/MM/YYYY
  let match =
    text.match(
      /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/
    );

  if (match) {

    const day =
      match[1].padStart(2, '0');

    const month =
      match[2].padStart(2, '0');

    return `${match[3]}-${month}-${day}`;
  }

  // YYYY-MM-DD
  match =
    text.match(
      /^(\d{4})-(\d{2})-(\d{2})$/
    );

  if (match) {
    return text;
  }

  return null;
}


