  const text = String(value).trim();

  return text || null;
}


function toNumber(value) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  const num = Number(value);

  return Number.isFinite(num)
    ? num
    : null;
}


function isValidISODate(value) {
  const text = normalizeText(value);

  if (!text) {
    return false;
  }

  const match = text.match(
    /^(\d{4})-(\d{2})-(\d{2})$/
  );

  if (!match) {
    return false;
  }

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);

  const date = new Date(
    Date.UTC(year, month - 1, day)
  );

  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}


function isFutureDate(value, maxFutureDays = 0) {
  if (!isValidISODate(value)) {
    return false;
  }

  const invoiceDate = new Date(
    `${value}T00:00:00Z`
  );

  const limit = new Date();

  limit.setUTCDate(
    limit.getUTCDate() + maxFutureDays
  );

  return invoiceDate.getTime() > limit.getTime();
}


function validTaxId(value) {
  const text = normalizeText(value);

  if (!text) {
    return false;
  }

  // Validación genérica.
  // Permite RUC/NIF/VAT nacionales o extranjeros.
  const cleaned = text.replace(
    /[^A-Za-z0-9]/g,
    ''
  );

  return (
    cleaned.length >= 8 &&
    cleaned.length <= 20
  );
}


