/**
 * Limpia respuestas tipo:
 *
 * ```json
 * { ... }
 * ```
 */
function cleanJsonString(value) {

  return String(value ?? '')
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();
}


/**
 * Intenta interpretar la respuesta del Agent.
 *
 * Soporta:
 * - JSON puro
 * - ```json ... ```
 * - texto accidental alrededor del JSON
 */
function parseAgentJson(value) {

  const cleaned =
    cleanJsonString(value);

  if (!cleaned) {
    return null;
  }


  // ----------------------------
  // Intento 1: JSON puro
  // ----------------------------

  try {

    const parsed =
      JSON.parse(cleaned);

    if (
      parsed &&
      typeof parsed === 'object' &&
      !Array.isArray(parsed)
    ) {
      return parsed;
    }

  } catch {
    // Continuar al segundo intento
  }


  // ----------------------------
  // Intento 2:
  // extraer primer { ... último }
  // ----------------------------

  const start =
    cleaned.indexOf('{');

  const end =
    cleaned.lastIndexOf('}');


  if (
    start !== -1 &&
    end !== -1 &&
    end > start
  ) {

    const candidate =
      cleaned.slice(
        start,
        end + 1
      );

    try {

      const parsed =
        JSON.parse(candidate);

      if (
        parsed &&
        typeof parsed === 'object' &&
        !Array.isArray(parsed)
      ) {
        return parsed;
      }

    } catch {
      return null;
    }
  }

  return null;
}


/**
 * Convierte confidence a escala 0-1.
 *
 * Soporta:
 *
 * 0.95
 * "0.95"
 * 95 → 0.95
 */
function normalizeConfidence(value) {

  let number =
    Number(value ?? 0);

  if (!Number.isFinite(number)) {
    return 0;
  }


  // Por si el modelo devuelve 95
  // en vez de 0.95
  if (
    number > 1 &&
    number <= 100
  ) {
    number =
      number / 100;
  }


  // Clamp 0-1
  return Math.min(
    1,
    Math.max(
      0,
      number
    )
  );
}


/**
 * Convierte valores tipo:
 *
 * SI
 * NO
 * TRUE
 * FALSE
 * 1
 * 0
 *
 * a boolean/null.
 */
function normalizeBoolean(value) {

  if (value === true) {
    return true;
  }

  if (value === false) {
    return false;
  }


  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }


  const normalized =
    String(value)
      .trim()
      .toUpperCase();


  if (
    [
      'SI',
      'SÍ',
      'YES',
      'TRUE',
      '1'
    ].includes(normalized)
  ) {
    return true;
  }


  if (
    [
      'NO',
      'FALSE',
      '0'
    ].includes(normalized)
  ) {
    return false;
  }


  return null;
}


/**
 * Normaliza políticas que pueden contener:
 *
 * SI
 * NO
 * DEPENDE
 *
 * Retorna:
 *
 * YES
 * NO
 * CONDITIONAL
 * UNKNOWN
 */
function normalizeReviewStatus(value) {

  if (value === true) {
    return 'YES';
  }

  if (value === false) {
    return 'NO';
  }


  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return 'UNKNOWN';
  }


  const normalized =
    String(value)
      .trim()
      .toUpperCase();


  if (
    [
      'SI',
      'SÍ',
      'YES',
      'TRUE',
      '1'
    ].includes(normalized)
  ) {
    return 'YES';
  }


  if (
    [
      'NO',
      'FALSE',
      '0'
    ].includes(normalized)
  ) {
    return 'NO';
  }


  if (
    [
      'DEPENDE',
      'CONDITIONAL',
      'CONDICIONAL',
      'REVIEW'
    ].includes(normalized)
  ) {
    return 'CONDITIONAL';
  }


  return 'UNKNOWN';
}


/**
 * Convierte un importe a Number/null.
 *
 * Soporta:
 *
 * 40
 * "40"
 * "40.00"
 * "40,00"
 * "S/ 40.00"
 */
function nullableNumber(value) {

  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }


  if (typeof value === 'number') {

    return Number.isFinite(value)
      ? value
      : null;
  }


  let text =
    String(value)
      .trim()
      .replace(/\s/g, '')
      .replace(/[^\d,.\-]/g, '');


  if (!text) {
    return null;
  }


  const lastComma =
    text.lastIndexOf(',');

  const lastDot =
    text.lastIndexOf('.');


  // 1.234,56
  if (
    lastComma > lastDot
  ) {

    text =
      text
        .replace(/\./g, '')
        .replace(',', '.');
  }

  // 1,234.56
  else if (
    lastDot > lastComma &&
    lastComma !== -1
  ) {

    text =
      text.replace(/,/g, '');
  }

  // 40,50
  else if (
    lastComma !== -1 &&
    lastDot === -1
  ) {

    text =
      text.replace(',', '.');
  }


  const number =
    Number(text);


  return Number.isFinite(number)
    ? number
    : null;
}


/**
 * Normaliza arrays de strings.
 */
function normalizeArray(value) {

  if (!Array.isArray(value)) {
    return [];
  }


  return value
    .map(
      item =>
        String(item ?? '').trim()
    )
    .filter(Boolean);
}


/**
