  // DD/MM/YYYY
  // DD-MM-YYYY
  // DD.MM.YYYY
  let match =
    text.match(
      /^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{2,4})$/
    );

  if (match) {

    day =
      Number(match[1]);

    month =
      Number(match[2]);

    year =
      Number(match[3]);

    if (year < 100) {
      year += 2000;
    }
  }

  else {

    // YYYY-MM-DD
    // YYYY/MM/DD
    match =
      text.match(
        /^(\d{4})[\/.\-](\d{1,2})[\/.\-](\d{1,2})$/
      );

    if (!match) {
      return null;
    }

    year =
      Number(match[1]);

    month =
      Number(match[2]);

    day =
      Number(match[3]);
  }

  if (
    !Number.isInteger(year) ||
    !Number.isInteger(month) ||
    !Number.isInteger(day)
  ) {
    return null;
  }

  const date =
    new Date(
      Date.UTC(
        year,
        month - 1,
        day
      )
    );

  // Evita fechas imposibles:
  // 31/02/2025, etc.
  if (
    date.getUTCFullYear() !== year ||
    date.getUTCMonth() !== month - 1 ||
    date.getUTCDate() !== day
  ) {
    return null;
  }

  const iso =
    [
      String(year).padStart(4, '0'),
      String(month).padStart(2, '0'),
      String(day).padStart(2, '0'),
    ].join('-');

  return {
    iso,
    timestamp:
      date.getTime(),
  };
}


// ============================================================
// EXTRAER FECHA DE INGRESO / CHECK-IN
// ============================================================

function extractCheckIn(text) {

  const patterns = [

    /(?:FECHA\s+(?:DE\s+)?)?INGRESO\s*[:\-]?\s*(\d{1,2}[\/.\-]\d{1,2}[\/.\-]\d{2,4}|\d{4}[\/.\-]\d{1,2}[\/.\-]\d{1,2})/i,

    /(?:FECHA\s+(?:DE\s+)?)?ENTRADA\s*[:\-]?\s*(\d{1,2}[\/.\-]\d{1,2}[\/.\-]\d{2,4}|\d{4}[\/.\-]\d{1,2}[\/.\-]\d{1,2})/i,

    /CHECK\s*[- ]?\s*IN\s*[:\-]?\s*(\d{1,2}[\/.\-]\d{1,2}[\/.\-]\d{2,4}|\d{4}[\/.\-]\d{1,2}[\/.\-]\d{1,2})/i,
  ];

  for (const regex of patterns) {

    const match =
      text.match(regex);

    if (match?.[1]) {

      const parsed =
        parseDate(match[1]);

      if (parsed) {
        return parsed;
      }
    }
  }

  return null;
}


// ============================================================
// EXTRAER FECHA DE SALIDA / CHECK-OUT
// ============================================================

function extractCheckOut(text) {

  const patterns = [

    /(?:FECHA\s+(?:DE\s+)?)?SALIDA\s*[:\-]?\s*(\d{1,2}[\/.\-]\d{1,2}[\/.\-]\d{2,4}|\d{4}[\/.\-]\d{1,2}[\/.\-]\d{1,2})/i,

    /CHECK\s*[- ]?\s*OUT\s*[:\-]?\s*(\d{1,2}[\/.\-]\d{1,2}[\/.\-]\d{2,4}|\d{4}[\/.\-]\d{1,2}[\/.\-]\d{1,2})/i,
  ];

  for (const regex of patterns) {

    const match =
      text.match(regex);

    if (match?.[1]) {

      const parsed =
        parseDate(match[1]);

      if (parsed) {
        return parsed;
      }
    }
  }

  return null;
}


// ============================================================
// RANGO TIPO:
// "DEL 17/03/2025 AL 21/03/2025"
// "DESDE 17/03/2025 HASTA 21/03/2025"
// ============================================================

function extractStayRange(text) {

  const regex =
    /(?:DEL|DESDE)\s*(\d{1,2}[\/.\-]\d{1,2}[\/.\-]\d{2,4}|\d{4}[\/.\-]\d{1,2}[\/.\-]\d{1,2})\s*(?:AL|HASTA)\s*(\d{1,2}[\/.\-]\d{1,2}[\/.\-]\d{2,4}|\d{4}[\/.\-]\d{1,2}[\/.\-]\d{1,2})/i;

  const match =
    text.match(regex);

  if (!match) {
    return null;
  }

  const checkIn =
    parseDate(match[1]);

  const checkOut =
    parseDate(match[2]);

  if (
    !checkIn ||
    !checkOut
  ) {
    return null;
  }

  return {
    checkIn,
    checkOut,
  };
}


// ============================================================
// EXTRAER NÚMERO DE NOCHES EXPLÍCITO
// ============================================================
//
// Ejemplos:
//
// "ALOJAMIENTO 04 NOCHES"
// "4 NOCHES"
// "NOCHES: 4"
// "4 DÍAS DE ALOJAMIENTO"
//
// No interpretamos un número aislado como noches.
// ============================================================

function extractExplicitNights(text) {

  const values = [];

  const patterns = [

    /\b(?:ALOJAMIENTO|HOSPEDAJE|ESTAD[IÍ]A)[\s\S]{0,80}?(\d{1,3})\s*NOCHES?\b/gi,

    /\b(\d{1,3})\s*NOCHES?\b/gi,

    /\bNOCHES?\s*[:\-]?\s*(\d{1,3})\b/gi,

    /\b(\d{1,3})\s*D[IÍ]AS?\s+DE\s+(?:ALOJAMIENTO|HOSPEDAJE|ESTAD[IÍ]A)\b/gi,
  ];

  for (const regex of patterns) {

    let match;

    while (
      (match = regex.exec(text)) !== null
    ) {

      const value =
        Number(match[1]);

      if (
        Number.isInteger(value) &&
        value > 0 &&
        value <= MAX_LODGING_NIGHTS
      ) {
        values.push(value);
      }
    }
  }

  return [
    ...new Set(values)
  ];
}


// ============================================================
// DATOS PRINCIPALES
// ============================================================

const total =
  toNumber(j.total);

const policyLimit =
  toNumber(j.policyLimit);

const expenseCategory =
  normalizeStatus(
    j.expenseCategory
  );

const isLodging =
  expenseCategory === 'LODGING';


const policyAllowed =
  j.policyAllowed === true;

const policyExplicitlyRejected =
  j.policyAllowed === false;

const policyFound =
  j.policyFound === true;

const toolUsed =
  j.toolUsed === true;

const agentResponseParsed =
  j.agentResponseParsed === true;

const classificationValid =
  j.classificationValid === true;

const policyContextReady =
  j.policyContextReady === true;

const expenseConfidence =
  toNumber(j.expenseConfidence) ?? 0;

const meetsConfidence =
  j.expenseMeetsConfidenceThreshold === true;

const restricted =
  j.containsPotentiallyRestrictedItems === true;

const requiresHumanReviewFromAgent =
  j.requiresHumanReview === true;

const policyReviewStatus =
  normalizeStatus(
    j.policyRequiresReviewStatus
  );

const taxReviewStatus =
  normalizeStatus(
    j.taxReviewStatus
  );

const rawText =
  String(
    j.rawText ??
    ''
  )
    .replace(/\u00A0/g, ' ')
    .trim();


// ============================================================
// EVALUACIÓN ESPECIAL DE HOSPEDAJE
// ============================================================

let lodgingCheckIn = null;
let lodgingCheckOut = null;

let lodgingExplicitNights = null;
let lodgingDateNights = null;

let lodgingNights = null;
let lodgingNightsSource = null;

let lodgingNightsConflict = false;

let lodgingAmountPerNight = null;

let lodgingEvaluationOk =
  isLodging
    ? false
    : null;


// ============================================================
// SOLO SE EJECUTA PARA LODGING
// ============================================================

if (isLodging) {

  // ----------------------------------------------------------
  // 1. Buscar noches explícitas
  // ----------------------------------------------------------

  const explicitNights =
    extractExplicitNights(
      rawText
    );

  // Si encontramos exactamente una cantidad coherente.
  if (explicitNights.length === 1) {

    lodgingExplicitNights =
      explicitNights[0];
  }

  // Si el propio texto contiene cantidades contradictorias.
  else if (explicitNights.length > 1) {

    lodgingNightsConflict =
      true;
  }


  // ----------------------------------------------------------
  // 2. Buscar check-in / check-out
  // ----------------------------------------------------------

  let checkIn =
    extractCheckIn(
      rawText
    );

  let checkOut =
    extractCheckOut(
      rawText
    );


  // ----------------------------------------------------------
  // 3. Si no encontramos etiquetas, buscar rango
  // ----------------------------------------------------------

  if (
    !checkIn ||
    !checkOut
  ) {

    const range =
      extractStayRange(
        rawText
      );

    if (range) {

      checkIn =
        checkIn ??
        range.checkIn;

      checkOut =
        checkOut ??
        range.checkOut;
    }
  }


  lodgingCheckIn =
    checkIn?.iso ??
    null;

  lodgingCheckOut =
    checkOut?.iso ??
    null;


  // ----------------------------------------------------------
  // 4. Calcular noches por diferencia de fechas
  // ----------------------------------------------------------

  if (
    checkIn &&
    checkOut
  ) {

    const millisecondsPerDay =
      24 * 60 * 60 * 1000;

    const difference =
      (
        checkOut.timestamp -
        checkIn.timestamp
      ) /
      millisecondsPerDay;

    if (
      Number.isInteger(difference) &&
      difference > 0 &&
      difference <= MAX_LODGING_NIGHTS
    ) {

      lodgingDateNights =
        difference;
    }
  }


  // ----------------------------------------------------------
  // 5. Resolver cantidad definitiva de noches
  // ----------------------------------------------------------

  // Tenemos texto + fechas y coinciden.
  if (
    lodgingExplicitNights !== null &&
    lodgingDateNights !== null
  ) {

    if (
      lodgingExplicitNights ===
      lodgingDateNights
    ) {

      lodgingNights =
        lodgingExplicitNights;

      lodgingNightsSource =
        'TEXT_AND_DATES';
    }

    else {

      // Ejemplo:
      // texto dice 4 noches
      // fechas dicen 3 noches
      lodgingNightsConflict =
        true;

      lodgingNights =
        null;

      lodgingNightsSource =
        'CONFLICT';
    }
  }

  // Solo existe cantidad explícita.
  else if (
    lodgingExplicitNights !== null
  ) {

    lodgingNights =
      lodgingExplicitNights;

    lodgingNightsSource =
      'TEXT';
  }

  // Solo tenemos fechas.
  else if (
    lodgingDateNights !== null
  ) {

    lodgingNights =
      lodgingDateNights;

    lodgingNightsSource =
      'DATES';
  }


  // ----------------------------------------------------------
  // 6. Calcular costo por noche
  // ----------------------------------------------------------

  if (
    total !== null &&
    total > 0 &&
    lodgingNights !== null &&
    lodgingNights > 0 &&
    !lodgingNightsConflict
  ) {

    lodgingAmountPerNight =
      roundMoney(
        total /
        lodgingNights
      );

    lodgingEvaluationOk =
      lodgingAmountPerNight !== null;
  }
}


// ============================================================
// BASE DE COMPARACIÓN DE POLÍTICA
// ============================================================
//
// Normal:
// total
//
// Hospedaje:
// total / noches
// ============================================================

let policyComparisonBasis =
  'TOTAL';

let policyComparisonAmount =
  total;


if (isLodging) {

  policyComparisonBasis =
    'PER_NIGHT';

  policyComparisonAmount =
    lodgingEvaluationOk
      ? lodgingAmountPerNight
      : null;
}


// ============================================================
// CÁLCULO DE LÍMITE
// ============================================================

const policyLimitConfigured =
  policyLimit !== null &&
  policyLimit >= 0;


let withinPolicyLimit = null;
let amountOverLimit = null;
let policyUsagePercent = null;


if (
  policyComparisonAmount !== null &&
  policyLimitConfigured
) {

  withinPolicyLimit =
    policyComparisonAmount <=
    policyLimit + MONEY_TOLERANCE;


  amountOverLimit =
    policyComparisonAmount > policyLimit
      ? roundMoney(
          policyComparisonAmount -
          policyLimit
        )
      : 0;


  if (policyLimit > 0) {

    policyUsagePercent =
      Number(
        (
          (
            policyComparisonAmount /
            policyLimit
          ) *
          100
        ).toFixed(2)
      );
  }
}


// ============================================================
// RAZONES
// ============================================================

const reviewReasons = [];
const rejectReasons = [];
const validationWarnings = [];


// ============================================================
// VALIDACIONES TÉCNICAS
// ============================================================

if (!agentResponseParsed) {

  reviewReasons.push(
    'AGENT_RESPONSE_NOT_PARSED'
  );
}


if (!classificationValid) {

  reviewReasons.push(
    'INVALID_EXPENSE_CLASSIFICATION'
  );
}


if (!meetsConfidence) {

  reviewReasons.push(
    'LOW_CLASSIFICATION_CONFIDENCE'
  );
}


if (!toolUsed) {

  reviewReasons.push(
    'POLICY_TOOL_NOT_USED'
  );
}


if (!policyFound) {

  reviewReasons.push(
    'POLICY_NOT_FOUND'
  );
}


if (!policyContextReady) {

  reviewReasons.push(
    'POLICY_CONTEXT_NOT_READY'
  );
}


// ============================================================
// VALIDACIÓN DE TOTAL
// ============================================================

if (
  total === null ||
  total <= 0
) {

  reviewReasons.push(
    'INVALID_TOTAL_FOR_POLICY'
  );
}


// ============================================================
// VALIDACIONES ESPECIALES DE HOSPEDAJE
// ============================================================

if (isLodging) {

  if (lodgingNightsConflict) {

    reviewReasons.push(
      'LODGING_NIGHTS_CONFLICT'
    );
  }


  if (
    lodgingNights === null ||
    lodgingNights <= 0
  ) {

    reviewReasons.push(
      'LODGING_NIGHTS_NOT_DETERMINED'
    );
  }


  if (
    lodgingCheckIn &&
    lodgingCheckOut &&
    lodgingDateNights === null
  ) {

    reviewReasons.push(
      'LODGING_INVALID_STAY_DATES'
    );
  }


  if (
    lodgingNights !== null &&
    lodgingAmountPerNight === null
  ) {

    reviewReasons.push(
      'LODGING_AMOUNT_PER_NIGHT_NOT_CALCULATED'
    );
  }


  // Información útil para auditoría.
  if (
    lodgingNightsSource === 'TEXT'
  ) {

    validationWarnings.push(
      'LODGING_NIGHTS_OBTAINED_FROM_TEXT'
    );
  }


  if (
    lodgingNightsSource === 'DATES'
  ) {

    validationWarnings.push(
      'LODGING_NIGHTS_OBTAINED_FROM_DATES'
    );
  }


  if (
    lodgingNightsSource ===
    'TEXT_AND_DATES'
  ) {

    validationWarnings.push(
      'LODGING_NIGHTS_CONFIRMED_BY_TEXT_AND_DATES'
    );
  }
}


// ============================================================
// POLÍTICA PERMITIDO / NO PERMITIDO
// ============================================================

if (policyExplicitlyRejected) {

  rejectReasons.push(
    'CATEGORY_NOT_ALLOWED_BY_POLICY'
  );
}


if (
  policyFound &&
  j.policyAllowed === null
) {

  reviewReasons.push(
    'POLICY_ALLOWED_VALUE_UNKNOWN'
  );
}


// ============================================================
// LÍMITE DE MONTO
// ============================================================

if (
  REQUIRE_POLICY_LIMIT &&
  !policyLimitConfigured
) {

  reviewReasons.push(
    'POLICY_LIMIT_NOT_CONFIGURED'
  );
}


if (
  withinPolicyLimit === false
) {

  // Superar el límite genera revisión humana,
  // no rechazo automático.
  //
  // Para LODGING:
  // compara importe por noche.
  //
  // Para otras categorías:
  // compara total.
  reviewReasons.push(
    'AMOUNT_EXCEEDS_POLICY_LIMIT'
  );
}


// ============================================================
// PRODUCTOS RESTRINGIDOS
// ============================================================

if (restricted) {

  reviewReasons.push(
    'POTENTIALLY_RESTRICTED_ITEMS'
  );
}


// ============================================================
// REVISIÓN DEFINIDA EN POLÍTICA
// ============================================================

if (
  policyReviewStatus === 'YES' ||
  policyReviewStatus === 'CONDITIONAL'
) {

  reviewReasons.push(
    'POLICY_REQUIRES_REVIEW'
  );
}


// ============================================================
// REVISIÓN TRIBUTARIA
// ============================================================

if (
  taxReviewStatus === 'YES' ||
  taxReviewStatus === 'CONDITIONAL'
) {

  reviewReasons.push(
    'TAX_REVIEW_REQUIRED'
  );
}


// ============================================================
// REVISIÓN PEDIDA POR EL AGENTE
// ============================================================

if (requiresHumanReviewFromAgent) {

  reviewReasons.push(
    'AGENT_REQUESTED_HUMAN_REVIEW'
  );
}


// ============================================================
// ELIMINAR RAZONES REPETIDAS
// ============================================================

const uniqueReviewReasons =
  [...new Set(reviewReasons)];

const uniqueRejectReasons =
  [...new Set(rejectReasons)];

const uniqueValidationWarnings =
  [...new Set(validationWarnings)];


// ============================================================
// DECISIÓN FINAL
// ============================================================

let policyDecision =
  'REVIEW';


// REJECT tiene prioridad máxima.
if (
  uniqueRejectReasons.length > 0
) {

  policyDecision =
    'REJECT';
}


// Si existen razones de revisión.
else if (
  uniqueReviewReasons.length > 0
) {

  policyDecision =
    'REVIEW';
}


// Todo correcto.
else {

  policyDecision =
    'ALLOW';
}


// ============================================================
// FLAGS
// ============================================================

const policyAutoApproved =
  policyDecision === 'ALLOW';

const policyNeedsHumanApproval =
  policyDecision === 'REVIEW';

const policyRejected =
  policyDecision === 'REJECT';


// ============================================================
// ESTADO DE EVALUACIÓN
// ============================================================
//
// Para hospedaje también necesitamos haber calculado
// correctamente las noches.
// ============================================================

const policyEvaluationOk =
  agentResponseParsed &&
  total !== null &&
  policyFound &&
  (
    !isLodging ||
    lodgingEvaluationOk === true
  );


// ============================================================
// LABEL
// ============================================================

const POLICY_DECISION_LABELS = {

  ALLOW:
    'Cumple política',

  REVIEW:
    'Requiere revisión humana',

  REJECT:
    'No permitido por política',
};


const policyDecisionLabel =
  POLICY_DECISION_LABELS[
    policyDecision
  ];


// ============================================================
// SALIDA
// ============================================================

return {

  json: {

    // --------------------------------------------------------
    // Conservamos todo P01-P07.3
    // --------------------------------------------------------

    ...j,


    // --------------------------------------------------------
    // Base utilizada para comparar política
    // --------------------------------------------------------

    policyComparisonBasis,

    policyComparisonAmount,


    // --------------------------------------------------------
    // Hospedaje
    // --------------------------------------------------------

    isLodging,

    lodgingCheckIn,

    lodgingCheckOut,

    lodgingExplicitNights,

    lodgingDateNights,

    lodgingNights,

    lodgingNightsSource,

    lodgingNightsConflict,

    lodgingAmountPerNight,

    lodgingEvaluationOk,


    // --------------------------------------------------------
    // Resultado monetario
    // --------------------------------------------------------

    policyLimitConfigured,

    withinPolicyLimit,

    amountOverLimit,

    policyUsagePercent,


    // --------------------------------------------------------
    // P07.4
    // --------------------------------------------------------

    policyEvaluationOk,

    policyDecision,

    policyDecisionLabel,


    // --------------------------------------------------------
    // Flags para IF / Switch
    // --------------------------------------------------------

    policyAutoApproved,

    policyNeedsHumanApproval,

    policyRejected,


    // --------------------------------------------------------
    // Explicabilidad
    // --------------------------------------------------------

    policyReviewReasons:
      uniqueReviewReasons,

    policyRejectReasons:
      uniqueRejectReasons,

    policyValidationWarnings:
      uniqueValidationWarnings,


    // --------------------------------------------------------
    // Auditoría
    // --------------------------------------------------------

    policyEvaluatedAt:
      new Date().toISOString(),
  },


  // Conservamos JPG / PDF / XML
  binary:
    item.binary,
};

// ============================================================
// P09.9 - PREPARAR RESULTADO FINAL
// ============================================================

const item = $input.item;
const j = item.json ?? {};


// ============================================================
// 1. DETERMINAR TIPO DE APROBACIÓN
// ============================================================

const humanApproved =
  j.humanApproved === true ||
  j.humanApprovalStatus === 'APPROVED';

const autoApproved =
  j.policyDecision === 'ALLOW' &&
  !humanApproved;


// ============================================================
// 2. ESTADO FINAL
// ============================================================

let finalStatus = 'PROCESSED';
let finalStatusLabel = 'Procesada';
let approvalType = 'NONE';

if (autoApproved) {

  finalStatus =
    'AUTO_APPROVED';

  finalStatusLabel =
    'Aprobada automáticamente';

  approvalType =
    'AUTOMATIC';
}

if (humanApproved) {

  finalStatus =
    'HUMAN_APPROVED';

  finalStatusLabel =
    'Aprobada manualmente';

  approvalType =
    'HUMAN';
}


// ============================================================
// 3. DESTINATARIO
// ============================================================

const recipientEmail =
  String(
    j.senderEmail ||
    j.collaboratorEmail ||
    ''
  )
  .trim()
  .toLowerCase();


// ============================================================
// 4. VALIDAR EMAIL
// ============================================================

const recipientEmailValid =
  /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    .test(recipientEmail);


// ============================================================
// 5. ASUNTO
// ============================================================

const documentNumber =
  j.documentNumber ||
  'SIN-NUMERO';

const finalEmailSubject =
  `Rendición ${documentNumber} - ${finalStatusLabel}`;


// ============================================================
// 6. SALIDA
// ============================================================

return {
  json: {

    ...j,

    approvalType,

    finalStatus,
    finalStatusLabel,

    recipientEmail,
    recipientEmailValid,

    finalEmailSubject,

    finalApproved:
      autoApproved ||
      humanApproved,

    finalProcessedAt:
      new Date().toISOString(),
  },

  binary:
    item.binary,
};

// ============================================================
// P09.11 - PREPARAR RECHAZO FINAL
// ============================================================
//
// Puede recibir:
// A) REJECT directo de la política
// B) REVIEW rechazado por una persona
//
// Genera un formato único para la notificación y registro.
// ============================================================

const item = $input.item;
const j = item.json ?? {};


// ============================================================
// 1. IDENTIFICAR ORIGEN DEL RECHAZO
// ============================================================

const humanRejected =
  j.humanApproved === false ||
  j.humanApprovalStatus === 'REJECTED';

const policyRejected =
  j.policyDecision === 'REJECT';


// ============================================================
// 2. DETERMINAR TIPO Y MENSAJE
// ============================================================

let rejectionType = 'POLICY';
let finalStatusLabel = 'No permitida por la política';

if (humanRejected) {
  rejectionType = 'HUMAN';
  finalStatusLabel = 'Rechazada por el aprobador';
} else if (policyRejected) {
  rejectionType = 'POLICY';
  finalStatusLabel = 'No permitida por la política';
}


// ============================================================
// 3. DESTINATARIO
// ============================================================

const recipientEmail =
  String(
    j.senderEmail ||
    j.collaboratorEmail ||
    ''
  )
    .trim()
    .toLowerCase();

const recipientEmailValid =
  /^[^\s@]+@[^\s@]+\.[^\s@]+$/
    .test(recipientEmail);


// ============================================================
// 4. MOTIVOS
// ============================================================

const policyRejectReasons =
  Array.isArray(j.policyRejectReasons)
    ? j.policyRejectReasons
    : [];

const policyReviewReasons =
  Array.isArray(j.policyReviewReasons)
    ? j.policyReviewReasons
    : [];


// ============================================================
// 5. ESTADO FINAL
// ============================================================

const finalStatus = 'REJECTED';
const finalApproved = false;

const finalEmailSubject =
  `Rendición ${j.documentNumber || 'SIN-NUMERO'} - ${finalStatusLabel}`;

const finalProcessedAt =
  new Date().toISOString();


// ============================================================
// 6. SALIDA
// ============================================================

return {
  json: {
    ...j,

    finalApproved,
    finalStatus,
    finalStatusLabel,

    rejectionType,

    recipientEmail,
    recipientEmailValid,

    policyRejectReasons,
    policyReviewReasons,

    finalEmailSubject,
    finalProcessedAt,
  },

  binary: item.binary,
};

// 🧪 SIMULA: Gmail · Send and Wait for Approval
//
// El nodo real devuelve:
//   { datos: { aprobado: true|false, 'respondióEn': '...' } }
const caso = $('D00 · Caso de prueba (dummy)').first().json._caso ?? {};

if (caso.aprobacionHumana !== true && caso.aprobacionHumana !== false) {
  throw new Error(
    'Este caso llegó a la rama de aprobación humana pero no define ' +
    '"aprobacionHumana". Usa el caso 2 (aprueba) o el 3 (rechaza).'
  );
}

return {
  json: {
    datos: {
      aprobado: caso.aprobacionHumana === true,
      'respondióEn': new Date().toISOString(),
    },
    _simulado: 'gmail.sendAndWait',
  },
};

// ============================================================
// P09.2 - NORMALIZAR APROBACIÓN HUMANA
// ============================================================
//
// Objetivos:
// 1. Interpretar la respuesta del Gmail HITL.
// 2. Recuperar todos los datos originales de la factura.
// 3. Conservar el archivo binario.
// 4. Crear un booleano estable: humanApproved.
//
// V1:
// Trabajamos con una factura por ejecución.
// ============================================================


// ============================================================
// 1. RECUPERAR CONTEXTO ORIGINAL
// ============================================================

const sourceItem =
  $('Evaluar política (P18)').first();

if (!sourceItem) {
  throw new Error(
    'No se encontró el contexto original en "Evaluar política (P18)"'
  );
}

const source =
  sourceItem.json ?? {};


// ============================================================
// 2. RESPUESTA DEL NODO HITL
// ============================================================

const response =
  $json ?? {};


// ============================================================
// 3. EXTRAER VALOR DE APROBACIÓN
// ============================================================
//
// Tu salida actual:
//
// {
//   "datos": {
//     "aprobado": true,
//     "respondióEn": "..."
//   }
// }
//
// También dejamos compatibilidad con nombres ingleses,
// por si una actualización de n8n cambia la estructura.
// ============================================================

const rawApproved =
  response.datos?.aprobado ??
  response.data?.approved ??
  response.aprobado ??
  response.approved ??
  null;


// ============================================================
// 4. NORMALIZAR BOOLEANO
// ============================================================

function normalizeBoolean(value) {

  if (value === true) {
    return true;
  }

  if (value === false) {
    return false;
  }

  if (value === null || value === undefined) {
    return null;
  }

  const normalized =
    String(value)
      .trim()
      .toLowerCase();

  if (
    [
      'true',
      'verdadero',
      'yes',
      'si',
      'sí',
      'approved',
      'approve',
      'aprobado',
      'aprobar'
    ].includes(normalized)
  ) {
    return true;
  }

  if (
    [
      'false',
      'falso',
      'no',
      'rejected',
      'reject',
      'disapproved',
      'declined',
      'rechazado',
      'rechazar'
    ].includes(normalized)
  ) {
    return false;
  }

  return null;
}


const humanApproved =
  normalizeBoolean(rawApproved);


// ============================================================
// 5. FECHA/HORA DE RESPUESTA
// ============================================================

const humanApprovalRespondedAt =
  response.datos?.['respondióEn'] ??
  response.datos?.respondioEn ??
  response.data?.respondedAt ??
  response.respondedAt ??
  new Date().toISOString();


// ============================================================
// 6. ESTADO NORMALIZADO
// ============================================================

const humanApprovalResolved =
  humanApproved !== null;

let humanApprovalStatus =
  'UNKNOWN';

if (humanApproved === true) {
  humanApprovalStatus =
    'APPROVED';
}

if (humanApproved === false) {
  humanApprovalStatus =
    'REJECTED';
}


// ============================================================
// 7. RESULTADO FINAL
// ============================================================

return {
  json: {

    // Recuperamos todos los datos anteriores
    ...source,

    // Auditoría HITL
    approvalType:
      'HUMAN',

    humanApprovalResolved,

    humanApproved,

    humanApprovalStatus,

    humanApprovalRespondedAt,

    // Guardamos la respuesta original para auditoría
    humanApprovalRawResponse:
      response,

  },

  // Recuperamos el comprobante original
  binary:
    sourceItem.binary,
};

// 🧪 SIMULA: Gmail · enviar resumen final al colaborador
return {
  json: {
    ...$json,
    _correoSimulado: {
      para: $json.recipientEmail ?? null,
      asunto: $json.finalEmailSubject ?? null,
      estado: $json.finalStatusLabel ?? null,
    },
  },
  binary: $input.item.binary,
};

// 🧪 SIMULA: Gmail · enviar aviso de rendición no aprobada
return {
  json: {
    ...$json,
    _correoSimulado: {
      para: $json.recipientEmail ?? null,
      asunto: $json.finalEmailSubject ?? null,
      motivo: $json.rejectionType ?? null,
    },
  },
  binary: $input.item.binary,
};

// 🧪 SIMULA: Google Drive · subir archivo
//
// El nodo real devuelve { id, name, webViewLink } del archivo subido.
// Aquí devolvemos los IDs de los 12 PDF que ya están en la carpeta
// de prueba, para que los enlaces de la tabla abran de verdad.
const ARCHIVOS = {
  1:  '1OgRkAG5tjcLK-5rtMgjPfy_ykXoDSVXj',
  2:  '1zt0SNJ23IhP0WVHSLVTJ4hqVuGOH4v4Z',
  3:  '1a853gKcn94y298mXn4VaOFuddmgYzgPP',
  4:  '1w8nW_UPdb24o57v1ctYUJUBYlijeFH8N',
  5:  '19gFWfFipTboCK8zVY9HCzsmpQN1jzW0T',
  6:  '16nqM-PNftubQuCB319RfWLVh1TWhoiMW',
  7:  '1C12LjLjYOpKj6F1IQne07HU9waNLaQ5A',
  8:  '1elkMlqd-1MHP1VpAm3tqVZJRVCDGbKfj',
  9:  '1yewolnURpM4iNdE8JUHHsrHuR8aU0q7O',
  10: '1ZvMlra0p-z6NS34QdvCJBOLKe0GU9tfT',
  11: '1D267gbdZUWvb_YUsYUXZb1stiKuuv_zi',
  12: '1nYLYzzqplJWJGbi5E1XIJjOCRB_Uii_g',
